-- Kraljevstvo Znanja: jedinstveni katalog od približno 2300 imena.
-- Stari odabiri i identiteti kraljevstava ostaju netaknuti.
with candidates as (
 select a || ' ' || b as name, 2 as group_rank from unnest(ARRAY['Zlatni','Srebrni','Bakreni','Plavi','Crveni','Žuti','Zeleni','Ljubičasti','Sjeverni','Južni','Istočni','Zapadni','Vječni','Divlji','Odvažni','Tihi','Nepobjedivi','Lukavi','Tajanstveni','Nebeski','Kameni','Pustinjski','Planinski','Ledeni','Morski','Veliki','Mali','Izgubljeni','Beskrajni','Zagonetni','Čarobni','Mistični','Zaboravljeni','Noćni','Jutarnji','Veseli','Gvozdeni','Kraljevski','Zmajski','Drevni','Smaragdni','Svemirski','Vatreni','Nevidljivi','Brkati','Rasplesani','Kraljevski']::text[]) a cross join unnest(ARRAY['Sokol','Zmaj','Feniks','Vitez','Gusar','Kompas','Kaktus','Robot','Vulkan','Bunker','Dvorac','Sat','Atlas','Vuk','Orkan','Zvonik','Džin','Duh','Medvjed','Trubadur','Mač','Štit','Orao','Kameleon','Gnom','Jednorog','Svemirac','Mamut','Biser','Pauk','Zec','Tigar','Ris','Kondor','Kralj','Pekar','Bumbar','Gospodar','Labirint','Tornado','Mornar','Keks','Samuraj','Zmajolik','Povjesničar','Kovač','Kozmonaut','Šahist','Akrobat','Neptun']::text[]) b
 union all select a || ' ' || b as name, 3 as group_rank from unnest(ARRAY['Zlatna','Srebrna','Bakrena','Plava','Crvena','Žuta','Zelena','Ljubičasta','Sjeverna','Južna','Istočna','Zapadna','Vječna','Divlja','Odvažna','Tiha','Nepobjediva','Lukava','Tajanstvena','Nebeska','Kamena','Pustinjska','Planinska','Ledena','Morska','Velika','Mala','Izgubljena','Beskrajna','Zagonetna','Čarobna','Mistična','Zaboravljena','Noćna','Jutarnja','Vesela','Vatrena','Nevidljiva','Brkata','Rasplesana']::text[]) a cross join unnest(ARRAY['Magla','Lubenica','Zvijezda','Kruna','Knjižnica','Tvrđava','Galaksija','Sova','Ruža','Sfinga','Sablja','Zastava','Dolma','Iskra','Munja','Truba','Kornjača','Hobotnica','Panda','Lisica','Fregata','Kometа','Palača','Pustolovina','Maca','Kokica','Gusjenica','Kraljica','Karta','Glava','Bajka','Kula','Dolina','Planina','Laguna','Arka','Šifra','Tajna','Mandarina','Maslina','Čarolija','Piramida','Tastatura','Raketa','Kocka']::text[]) b
 union all select a || ' ' || b as name, 4 as group_rank from unnest(ARRAY['Zlatni','Srebrni','Plavi','Crveni','Zeleni','Crni','Bijeli','Vatreni','Ledeni','Pustinjski','Nebeski','Drevni','Divlji','Lukavi','Tajni','Nepobjedivi','Neustrašivi','Svemirski','Rasplesani','Čarobni','Ponosni','Zagonetni','Brkati','Veseli']::text[]) a cross join unnest(ARRAY['Vukovi','Pirati','Vitezovi','Mornari','Sokolovi','Roboti','Pustolovi','Povjesničari','Zmajevi','Šahisti','Astronauti','Kozmonauti','Ratnici','Kvizolovci','Slikari','Trubaduri','Kaktusi','Klovnovi','Alkemičari','Detektivi','Medvjedi','Panda Medvjedi','Čarobnjaci','Šumari','Zidari','Bardovi','Gusari','Kemičari','Putnici','Majstori','Pekari','Rudari','Ninja Ratnici','Samuraji','Kraljevi','Gnomovi','Čitatelji','Izumitelji','Istraživači','Mumiji']::text[]) b
 union all select a || ' ' || b as name, 5 as group_rank from unnest(ARRAY['Čuvari','Vladari','Nasljednici','Prijatelji','Tajni čuvari','Branitelji','Tragači','Gospodari','Duhovi','Ratnici','Vitezovi','Pirati','Glasnici','Kroničari','Čarobnjaci','Veseli stražari','Povratnici','Majstori','Nadglednici','Sinovi','Društvo','Red','Klan','Ceh','Bratstvo','Legija','Savez','Družina','Orkestar']::text[]) a cross join unnest(ARRAY['sjeverne svjetlosti','crvenog mjeseca','izgubljenog atlasa','zlatne lubenice','sedam mora','prašnjavih knjiga','letećih tanjura','noćne oluje','smaragdnog otoka','tajne pećine','kamenog mosta','pustinjskog sunca','prvog kompasa','zaboravljenih karata','nebeskog zvonika','čarobnog lonca','posljednjeg zmaja','tisuću pitanja','magličaste doline','plave zvijezde','zelene šume','zlatnog ključа','starog sata','velikog kviza','morske pjene','raskošnog dvorca','pametnog robota','rasplesane planete','skrivenog blaga','plamenog feniksa','ledenih planina','jutarnje magle','crnog bisera','žutog balona','srebrnog štita','tajnog prolaza','zvjezdanih prašina','žive enciklopedije','šarenih čarapa','gorskog vrha','čudne matematike','drevnih pisama','malog princa','slatkog bureka','posljednje galaksije','plave lagune']::text[]) b
 union all select a || ' ' || b as name, 6 as group_rank from unnest(ARRAY['Vukovi','Gusari','Pirati','Sokolovi','Čarobnjaci','Znanstvenici','Mornari','Pustolovi','Tragači','Samuraji','Kvizolovci','Osvajači','Bardovi','Putnici','Čuvari','Gnomovi','Vitezovi','Kroničari','Šahisti','Zvjezdari','Roboti','Astronomi','Mudraci','Trubaduri','Istraživači','Družina','Legija','Red','Ceh','Bratstvo','Klan','Orkestar','Draguljari','Sanjarі','Graditelji','Bubnjari','Pripovjedači','Alkemičari','Majstori','Kraljevi']::text[]) a cross join unnest(ARRAY['Jadrana','Dinare','Velebita','Karpata','Himalaje','Andromede','Atlantide','Neretve','Drine','Save','Dunava','Mjeseca','Marsa','Saturna','Venere','Plutona','Mediterana','Sahare','Amazone','Arktika','Antarktike','Alpa','Balkana','Hercegovine','Dalmacije','Istre','Slavonije','Bosne','Panonije','Hvara','Visa','Korčule','Bračа','Pelješca','Kvarnera','Svemira','Olimpa','Oceana','Sjevernog pola','Južnog pola','Toskane','Perzije','Egipta','Maje','Inka']::text[]) b
 union all select x, 1 as group_rank from unnest(ARRAY['Kvizilend','Kraljostan','Enciklopedijski Kaos','Dvadeset Metara Slave','Zadnji Bod','Prvi Točan','Bez Pomoćnog Kotača','Pitanje Nad Pitanjima','Čarobni Džep','Čupava Jednadžba','Planeta Kvizaša','Nedovršena Rečenica','Tajanstvena Tri Slova','Krušni Kraljevi','Akademija Palačinki','Naredba Čokolada','Klub Nepročitanih Knjiga','Zmaj od Papira','Svemirski Ćevap','Saturnov Dnevnik','Liga Slomljenih Kompasa','Kraljevstvo Odgovora','Burek i Zvijezde','Mali Veliki Atlas','Samo Jedno Pitanje','Moždani Vulkan','Kraljevstvo Kokica','Galaktička Pekarnica','Trinaesto Slovo','Hrabre Tipkovnice','Neobična Republika','Tajna Mrkve','Carstvo Ludih Ideja','Povratak Feniksa','Zelena Galaksija','Zmajev Doručak','Kabinet Neobičnih Čuda','Zemlja Šifri','Raskošni Kaos','Pjesma O Kompasu','Brigada Čajne Žličice','Otok Svojeglavih Robota','Kronike Šarenog Kišobrana','Nebeska Pekarnica','Katedrala Pitanja','Slastičarnica Mudrosti','Tornado od Slova','Palača Papirnatih Kruna','Tajni Red Mozgalica','Olimpijski Burek','Enciklopedija Snova','Udruga Bez Panike','Veliki Kviz Svemira','Laboratorij Legendi','Vijeće Zaboravljenih Karti','Narančasti Horizont','Kvantna Marmelada','Kraljevstvo Čudesa','Znanstvena Čarapa','Slovo do Slova','Legenda o Smijehu']::text[]) x
),
available as (
 select name,min(group_rank) as group_rank from candidates
 where char_length(name) between 5 and 72
 and not exists(select 1 from public.kz_names n where n.name=candidates.name)
 group by name
)
insert into public.kz_names(name)
select name from available
order by group_rank, md5(name)
limit greatest(0,2300 - (select count(*) from public.kz_names))
on conflict do nothing;
